import {CASES} from './history-cases.js?v=0.8.0';
export {CASES};
export const HISTORY_SOURCES=CASES.map(c=>({id:c.id,name:c.name+' · '+c.date,fact:c.fact,url:c.url}));
const CONTEXTS={baby:['亲子安全故事','照护者将历史案例转为安全的亲子活动，由照护者代选。'],kindergarten:['幼儿园故事讨论','老师用图片讲述真实历史，邀请你选择怎样完成一个小演示。'],primary:['小学历史活动','你在班级活动中讨论案例，提出一个小组方案。'],middle:['初中探究报告','你为历史探究报告比较证据、风险和不同方案。'],high:['高中综合讨论','你需要写明方案的代价与边界，不只写一个好听的结论。'],university:['本科实践课','你把历史案例改写成课程中的公共问题方案。'],master:['硕士案例研究','你需要区分因果证据、相关性和政策实施条件。'],phd:['博士研究复核','你必须保留反例，并说明历史经验能否迁移。'],preparation:['青年实践项目','你参加社区实践，用历史案例讨论小范围试点。'],clerk:['科员案情简报','你负责整理材料，提出供上级核验的建议，而非自行决定国家政策。'],township:['乡镇基层协商','你需要将历史经验用于本地具体服务，说明执行和居民反馈。'],county:['县域公共决策','你负责组织部门核实风险、预算与受影响人群。'],city:['城市跨区协调','你需要协调不同地区与专业团队，明确责任接口。'],province:['省域综合治理','你需要比较地区差异，避免统一模板造成损失。'],national:['国家重大决策','你需要比较长期影响、跨境协调与失控风险。'],retired:['退休经验整理','你整理历史与工作经验，帮助青年理解依据和教训，不再以原职务干预事务。']};
const EARLY={baby:[['保留安全观察，让家人耐心讲解','只追求刺激效果而忽略保护','因不能马上理解便不再交流'],'亲子互动借鉴的是安全观察，不要求婴儿理解公共决策。'],kindergarten:[['先观察比较，再一起动手验证','只跟着声音最大的同伴行动','只要演示好看就不检查过程'],'幼儿阶段侧重观察、分享和安全实践。'],primary:null};
export const HISTORY_QUESTIONS=Object.entries(CONTEXTS).flatMap(([pool,[label,context]])=>CASES.map(c=>({id:'history-'+pool+'-v8-'+c.id,pool,historyId:c.id,title:label+' · '+c.name,text:context+'\n史实线索：'+c.fact+'\n'+(EARLY[pool]?'活动目标：用安全的方式认识观察、验证和协作。':'情境改编：'+c.dilemma),options:EARLY[pool]?EARLY[pool][0]:c.options,answer:0,explanation:'情境改写，不复刻历史全部条件。'+(EARLY[pool]?EARLY[pool][1]:c.explanation)+' 判分依据为题设目标，不是宣称历史只有唯一正确道路。'})));
